
USE MedTest_Dev;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
GO
IF EXISTS (SELECT 1 FROM dbo.Patients)
BEGIN
    PRINT N'Пациенты уже есть, примеры не добавлялись.';
    SET NOEXEC ON;
END
GO
BEGIN TRANSACTION;
DECLARE @Doctor int = (SELECT TOP 1 Id FROM dbo.Users WHERE Role = 'Doctor' ORDER BY Id);
IF @Doctor IS NULL
BEGIN
    -- Пароль этой записи неизвестен никому: хеш и соль случайные, вход отключён.
    INSERT dbo.Users(Login, FullName, Role, IsActive, PasswordHash, Salt, Iterations)
    VALUES ('sample_doctor', N'Врач (примеры данных)', 'Doctor', 0, CRYPT_GEN_RANDOM(32), CRYPT_GEN_RANDOM(32), 210000);
    SET @Doctor = SCOPE_IDENTITY();
END;
DECLARE @p int, @e int;
DECLARE @Ind TABLE (Code varchar(16) PRIMARY KEY, Id int);
INSERT @Ind SELECT Code, Id FROM dbo.Indicators;


